// English Home Page with SEO + OpenGraph

import { sanity } from "@/lib/sanity";
import OpportunityCard from "@/components/OpportunityCard";
import LeadForm from "@/components/LeadForm";
import { useTranslations } from "next-intl";
import { motion } from "framer-motion";

// GLOBAL METADATA FOR THIS PAGE
export const metadata = {
  title: "GINKGO — Strategic Land Opportunities in Mexico",
  description:
    "Explore curated development opportunities across Mexico. Premium land assets for residential, commercial, and mixed-use projects.",
  openGraph: {
    title: "GINKGO — Strategic Land Opportunities",
    description:
      "Explore curated development opportunities across Mexico.",
    url: "https://ginkgo.mx/en",
    siteName: "GINKGO",
    images: [
      {
        url: "/images/og-default.jpg",
        width: 1200,
        height: 630,
        alt: "GINKGO — Strategic Land Opportunities"
      }
    ],
    locale: "en_US",
    type: "website"
  }
};

export const revalidate = 60;

async function getOpportunities() {
  return await sanity.fetch(`*[_type == "opportunity"]`);
}

export default async function HomePage() {
  const t = useTranslations("home");
  const opportunities = await getOpportunities();

  return (
    <main className="min-h-screen">
      {/* HERO */}
      <section
        className="h-[90vh] flex items-center justify-center bg-cover bg-center"
        style={{ backgroundImage: 'url(/images/hero.jpg)' }}
      >
        <div className="text-center text-white max-w-3xl px-4">
          <h1 className="text-5xl font-bold">{t("headline")}</h1>
          <p className="mt-4 text-xl">{t("subheadline")}</p>
        </div>
      </section>

      {/* FORM */}
      <section className="py-20 container mx-auto px-4">
        <LeadForm />
      </section>

      {/* FEATURED */}
      <motion.section
        className="py-20 container mx-auto px-4"
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <h2 className="text-3xl font-bold mb-10">{t("featured")}</h2>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
          {opportunities.slice(0, 3).map((op) => (
            <OpportunityCard key={op._id} data={op} locale="en" />
          ))}
        </div>
      </motion.section>
    </main>
  );
}
